560	#define PET_PLAY_DURATION_TICKS  12  /* 玩耍 ~6秒 */
561	#define PET_TOUCH_DURATION_TICKS 10  /* 抚摸 ~5秒（短爆发，防止快速循环闪烁） */
562	#define PET_CELEB_DURATION_TICKS 16  /* 庆祝 ~8秒 */
563	
564	static void pet_transition_to(dm_pet_state_t new_state, const char *why)
565	{
566	    dm_pet_state_t old = g_state;
567	    if (new_state == old)
568	    {
569	        /* 同态重入：刷新持续时间，防止残值为0导致立刻跳走 */
570	        if (old == PET_STATE_EAT)
571	            g_behavior_ticks_left = PET_EAT_DURATION_TICKS;
572	        else if (old == PET_STATE_PLAY)
573	            g_behavior_ticks_left = PET_PLAY_DURATION_TICKS;
574	        else if (old == PET_STATE_TOUCH)
575	            g_behavior_ticks_left = PET_TOUCH_DURATION_TICKS;
576	        else if (old == PET_STATE_CELEBRATE)
577	            g_behavior_ticks_left = PET_CELEB_DURATION_TICKS;
578	        else
579	            pet_select_behavior();
580	        return;
581	    }
582	    g_state = new_state;
583	    pet_apply_state_effects();
584	    pet_select_behavior();
585	
586	    /* 事件驱动态无行为池，设固定持续时间后自动回 IDLE */
587	    if (new_state == PET_STATE_EAT)
588	        g_behavior_ticks_left = PET_EAT_DURATION_TICKS;
589	    else if (new_state == PET_STATE_PLAY)
590	        g_behavior_ticks_left = PET_PLAY_DURATION_TICKS;
591	    else if (new_state == PET_STATE_TOUCH)
592	        g_behavior_ticks_left = PET_TOUCH_DURATION_TICKS;
593	    else if (new_state == PET_STATE_CELEBRATE)
594	        g_behavior_ticks_left = PET_CELEB_DURATION_TICKS;
595	
596	    LV_LOG_USER("[pet] %s → %s (%s)",
597	                dm_pet_state_name(old), dm_pet_state_name(new_state), why);
598	
599	    /* 进入饥饿状态 → 显示可点击喂食提示（PET.txt §8） */
600	    if (new_state == PET_STATE_HUNGRY)
601	        pet_show_hunger_alert();
602	    else
603	        pet_hide_hunger_alert();
604	}
605	
606	static void pet_apply_state_effects(void)
607	{
608	    switch (g_state)
609	    {
610	    case PET_STATE_SLEEP:
611	        /* 睡觉恢复精力 */
612	        g_pet.attrs.energy = clamp(g_pet.attrs.energy + 5, 0, 100);
613	        break;
614	    case PET_STATE_HAPPY:
615	    case PET_STATE_CELEBRATE:
616	        g_pet.attrs.happiness = clamp(g_pet.attrs.happiness + 2, 0, 100);
617	        break;
618	    case PET_STATE_SAD:
619	        /* 不额外惩罚，只是表现 */
620	        break;
621	    default:
622	        break;
623	    }
624	}
625	
626	/****************************************************************************
627	 * 行为选择（加权随机）
628	 ****************************************************************************/
629	
630	static const pet_behavior_t *pick_from_pool(const pet_behavior_t *pool,
631	                                            int count)
632	{
633	    int total = 0;
634	    for (int i = 0; i < count; i++)
635	        total += pool[i].weight;
636	    if (total <= 0) return &pool[0];
637	
638	    int r = rand() % total;
639	    for (int i = 0; i < count; i++)
640	    {
641	        r -= pool[i].weight;
642	        if (r < 0) return &pool[i];
643	    }
644	    return &pool[count - 1];
645	}
646	
647	static void pet_select_behavior(void)
648	{
649	    const pet_behavior_t *b = NULL;
650	
651	    switch (g_state)
652	    {
653	    case PET_STATE_IDLE:
654	        b = pick_from_pool(g_cat_idle, CAT_IDLE_COUNT);
655	        break;
656	    case PET_STATE_SLEEP:
657	        b = pick_from_pool(g_sleep_behaviors, SLEEP_COUNT);
658	        break;
659	    case PET_STATE_HAPPY:
660	        b = pick_from_pool(g_happy_behaviors, HAPPY_COUNT);
661	        break;
662	    case PET_STATE_SAD:
663	        b = pick_from_pool(g_sad_behaviors, SAD_COUNT);
664	        break;
665	    case PET_STATE_CELEBRATE:
666	        b = pick_from_pool(g_celebrate_behaviors, CELEBRATE_COUNT);
667	        break;
668	    case PET_STATE_HUNGRY:
669	        b = pick_from_pool(g_hungry_behaviors, HUNGRY_COUNT);
