265	static void settings_pet_name_cb(lv_event_t *e)
266	{
267	    (void)e;
268	    const dm_pet_data_t *pd = dm_pet_get_data();
269	    if (!pd) return;
270	
271	    /* 在当前 subpage overlay 上创建全屏遮罩（和 WiFi 密码输入同模式）
272	     * 不能直接在 settings scrollable card 上建 textarea+keyboard——
273	     * LVGL 9 键盘弹出时布局计算会崩 */
274	    lv_obj_t *subpage_overlay = lv_obj_get_parent(lv_event_get_current_target(e));
275	    /* 往上找到 subpage overlay（FLOATING 的全屏容器） */
276	    while (subpage_overlay && !lv_obj_has_flag(subpage_overlay, LV_OBJ_FLAG_FLOATING))
277	        subpage_overlay = lv_obj_get_parent(subpage_overlay);
278	    if (!subpage_overlay) return;
279	
280	    lv_obj_t *overlay = lv_obj_create(subpage_overlay);
281	    lv_obj_set_size(overlay, LV_PCT(100), LV_PCT(100));
282	    lv_obj_set_style_bg_color(overlay, lv_color_hex(0x000000), 0);
283	    lv_obj_set_style_bg_opa(overlay, LV_OPA_60, 0);
284	    lv_obj_set_style_border_width(overlay, 0, 0);
285	    lv_obj_set_style_pad_all(overlay, 0, 0);
286	    lv_obj_clear_flag(overlay, LV_OBJ_FLAG_SCROLLABLE);
287	    lv_obj_add_flag(overlay, LV_OBJ_FLAG_FLOATING);
288	    lv_obj_add_flag(overlay, LV_OBJ_FLAG_CLICKABLE); /* 吞点击防穿透 */
289	
290	    lv_obj_t *ta = lv_textarea_create(overlay);
291	    lv_obj_set_size(ta, DM(260), DM(44));
292	    lv_obj_align(ta, LV_ALIGN_TOP_MID, 0, DM(200));
293	    lv_textarea_set_one_line(ta, true);
294	    lv_textarea_set_max_length(ta, 15);
295	    lv_textarea_set_placeholder_text(ta, "输入名字（≤15字）");
296	    lv_textarea_set_text(ta, pd->name[0] ? pd->name : "旺财");
297	    lv_obj_set_style_text_font(ta, FONT_BODY, 0);
298	    lv_obj_set_style_bg_color(ta, lv_color_hex(0xFFFFFF), 0);
299	    lv_obj_set_style_radius(ta, DM(8), 0);
300	    lv_obj_set_style_border_width(ta, 1, 0);
301	    lv_obj_set_style_border_color(ta, lv_color_hex(0xCCCCCC), 0);
302	    lv_obj_add_flag(ta, LV_OBJ_FLAG_CLICKABLE);
303	
304	    g_pet_name_kb = dm_kb_create(overlay, ta, settings_pet_name_ready_cb, NULL);
305	}
