700	dm_kb_state_t *dm_kb_create(lv_obj_t *parent, lv_obj_t *ta,
701	                             dm_kb_ready_cb_t on_ready, void *user_data)
702	{
703	    if (!parent || !ta)
704	        return NULL;
705	
706	    dm_kb_state_t *state = lv_malloc(sizeof(dm_kb_state_t));
707	    if (!state)
708	        return NULL;
709	    memset(state, 0, sizeof(*state));
710	
711	    state->ta        = ta;
712	    state->on_ready  = on_ready;
713	    state->user_data = user_data;
714	
715	    lv_obj_t *kb = lv_keyboard_create(parent);
716	    lv_obj_set_size(kb, LV_PCT(100), LV_PCT(50));
717	    lv_obj_align(kb, LV_ALIGN_BOTTOM_MID, 0, 0);
718	    lv_obj_set_style_text_font(kb, &lv_font_montserrat_30, LV_PART_ITEMS);
719	    lv_obj_set_style_text_font(kb, &lv_font_montserrat_30, LV_PART_MAIN);
720	    lv_keyboard_set_textarea(kb, ta);
721	
722	    /* textarea 聚焦/失焦 → 显隐键盘 */
723	    lv_obj_add_event_cb(ta, dm_kb_ta_focused_cb, LV_EVENT_FOCUSED, state);
724	    lv_obj_add_event_cb(ta, dm_kb_ta_defocused_cb, LV_EVENT_DEFOCUSED, state);
725	
726	    /* 键盘 READY/CANCEL 事件 */
727	    lv_obj_add_event_cb(kb, dm_kb_event_cb, LV_EVENT_READY, state);
728	    lv_obj_add_event_cb(kb, dm_kb_event_cb, LV_EVENT_CANCEL, state);
729	
730	    /* 初始隐藏 */
731	    lv_obj_add_flag(kb, LV_OBJ_FLAG_HIDDEN);
732	
733	    state->kb = kb;
734	    return state;
735	}
